"""Pins the observable output of a full dry-run, so refactoring cannot change it unnoticed."""

from __future__ import annotations

import json
import subprocess
from pathlib import Path

import pytest

from ai_test_assistant.config import load_config
from ai_test_assistant.llm_client import LlmClient
from ai_test_assistant.pipeline import run_generate_tests_for_file, run_pr_assistant

GENERATED_HEADER = (
    "# This file was generated by AI Unit Test Assistant.\n"
    "# Review before committing.\n"
)
SUGGESTED_HEADER = (
    "# This is a suggested update generated by AI Unit Test Assistant.\n"
    "# Review before replacing the original test file.\n"
)


def _git(repo: Path, *args: str) -> None:
    subprocess.run(["git", *args], cwd=repo, check=True, capture_output=True)


def _write(repo: Path, rel: str, text: str) -> None:
    path = repo / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


@pytest.fixture(autouse=True)
def _no_settings_from_environment(monkeypatch: pytest.MonkeyPatch) -> None:
    for name in ("BASE_REF", "OUTPUT_DIR", "SUGGESTIONS_DIR", "REPORT_PATH",
                 "REPAIR_ATTEMPTS", "UPDATE_EXISTING_TESTS", "DRY_RUN"):
        monkeypatch.delenv(name, raising=False)


@pytest.fixture()
def pr_repo(tmp_path: Path) -> Path:
    """A feature branch that changes three files; checkout.py imports pricing.py."""
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init", "-q", "-b", "main")
    _git(repo, "config", "user.email", "dev@example.com")
    _git(repo, "config", "user.name", "dev")
    _write(repo, "shop/__init__.py", "")
    _write(repo, "shop/pricing.py", "def net_price(amount):\n    return round(amount, 2)\n")
    _write(
        repo,
        "shop/checkout.py",
        "from shop.pricing import net_price\n\n\n"
        "def total(amounts):\n    return net_price(sum(amounts))\n",
    )
    _write(repo, "shop/settings.py", "CURRENCY = 'EUR'\n")
    _write(
        repo,
        "tests/test_checkout.py",
        "from shop.checkout import total\n\n\ndef test_total():\n    assert total([1, 2]) == 3\n",
    )
    _git(repo, "add", ".")
    _git(repo, "commit", "-q", "-m", "base")

    _git(repo, "checkout", "-q", "-b", "feature")
    _write(
        repo,
        "shop/pricing.py",
        "def net_price(amount):\n    return round(amount, 2)\n\n\n"
        "def gross_price(amount, vat):\n    return round(amount * (1 + vat), 2)\n",
    )
    _write(
        repo,
        "shop/checkout.py",
        "from shop.pricing import net_price\n\n\n"
        "def total(amounts):\n    return net_price(sum(amounts))\n\n\n"
        "def count(amounts):\n    return len(amounts)\n",
    )
    _write(repo, "shop/settings.py", "CURRENCY = 'USD'\n")
    _git(repo, "commit", "-q", "-am", "feature")
    return repo


def _dry_run_config(repo: Path):
    return load_config(repo_root=repo, cli_overrides={"base_ref": "main", "dry_run": True})


def test_pr_run_report_order_statuses_and_files(pr_repo: Path) -> None:
    config = _dry_run_config(pr_repo)
    llm = LlmClient(config)

    result = run_pr_assistant(config, llm=llm)

    report = json.loads((pr_repo / "reports" / "ai-test-report.json").read_text(encoding="utf-8"))
    assert report["summary"] == {
        "changed_files": 3,
        "files_with_generated_tests": 2,
        "files_with_suggested_updates": 1,
        "passed_generated_tests": 2,
        "failed_generated_tests": 0,
    }
    assert report["changed_files"] == ["shop/pricing.py", "shop/checkout.py", "shop/settings.py"]
    assert report["import_cycle_files"] == []
    assert [
        (f["source_file"], f["status"], f["generated_test_file"], f["suggested_test_files"])
        for f in report["files"]
    ] == [
        ("shop/pricing.py", "passed", "tests/generated/test_shop_pricing_generated.py", []),
        (
            "shop/checkout.py",
            "passed",
            "tests/generated/test_shop_checkout_generated.py",
            ["reports/suggested-tests/tests/test_checkout.py"],
        ),
        ("shop/settings.py", "skipped", "", []),
    ]
    assert [f["message"] for f in report["files"]] == [
        "Generated tests passed.",
        "Generated tests passed.",
        "No public functions or methods to test.",
    ]
    assert report["files"][0]["pytest"]["passed"] is True
    assert report["files"][2]["pytest"] is None
    assert len(result.file_results) == 3
    # One generation per tested file plus one update for tests/test_checkout.py.
    assert llm.usage.calls == 3

    markdown = (pr_repo / "reports" / "ai-test-report.md").read_text(encoding="utf-8")
    assert "Changed production files: 3" in markdown
    assert "Files with suggested test updates: 1" in markdown
    sections = [markdown.index(f"### shop/{name}.py") for name in ("pricing", "checkout", "settings")]
    assert sections == sorted(sections)

    generated = (pr_repo / "tests" / "generated" / "test_shop_checkout_generated.py").read_text(encoding="utf-8")
    assert generated.startswith(GENERATED_HEADER)
    assert "def test_generated_placeholder" in generated
    suggested = (pr_repo / "reports" / "suggested-tests" / "tests" / "test_checkout.py").read_text(encoding="utf-8")
    assert suggested.startswith(SUGGESTED_HEADER)


def test_a_broken_file_is_reported_and_the_run_goes_on(pr_repo: Path) -> None:
    _write(pr_repo, "shop/broken.py", "def oops(:\n")
    _git(pr_repo, "add", ".")
    _git(pr_repo, "commit", "-q", "-m", "broken file")

    result = run_pr_assistant(_dry_run_config(pr_repo))

    by_name = {r.source_file.name: r for r in result.file_results}
    assert by_name["broken.py"].status == "error"
    assert by_name["broken.py"].message.startswith("Test generation failed: ")
    assert by_name["pricing.py"].status == "passed"


def test_single_file_run_writes_tests_but_no_suggestions(pr_repo: Path) -> None:
    config = _dry_run_config(pr_repo)

    result = run_generate_tests_for_file(config, pr_repo / "shop" / "checkout.py")

    assert result.status == "passed"
    assert result.message == "Generated tests passed."
    assert result.generated_test_file.resolve() == (
        pr_repo / "tests" / "generated" / "test_shop_checkout_generated.py"
    ).resolve()
    assert result.suggested_test_files == []
    assert not (pr_repo / "reports").exists()
